import heapq

def johnsons(n, edges):
    # add virtual source, run Bellman-Ford for potentials
    h = [0] * (n + 1)
    all_edges = edges + [(n, v, 0) for v in range(n)]
    for _ in range(n):
        for u, v, w in all_edges:
            if h[u] + w < h[v]:
                h[v] = h[u] + w
    graph = {u: [] for u in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w + h[u] - h[v]))  # reweight: non-negative
    result = []
    for src in range(n):
        dist = [float('inf')] * n
        dist[src] = 0
        pq = [(0, src)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                if d + w < dist[v]:
                    dist[v] = d + w
                    heapq.heappush(pq, (dist[v], v))
        result.append([d + h[v] - h[src] if d < float('inf') else None
                       for v, d in enumerate(dist)])
    return result

